private theorem evalRealPolynomial_ofFn_eq_sum (n : ℕ) (a : Fin n → ℝ) (z : ℂ) :
    evalRealPolynomial (Polynomial.ofFn n a) z =
      ∑ i : Fin n, ((a i : ℝ) : ℂ) * z ^ (i : ℕ)

